import { join, relative, resolve } from "node:path";
import { ControlPlane, type TaskSnapshot } from "../../../core/modules/task-control/control-plane";
import { readAsIsJson } from "../../../core/modules/context-resolution/configuration-resolver";
import { taskRecordNameFromConfiguration } from "../../../core/modules/task-control/task-record-policy";

export type OrientationSnapshot = {
  root: { status: string; nextAction: string };
  components: Array<Pick<TaskSnapshot, "path" | "status">>;
  open: Array<Pick<TaskSnapshot, "path" | "status" | "worker" | "blockers">>;
  changelog: { entry: string; residualRisk: string[] };
  openDecisions: string[];
  workingTree: string[] | "clean";
};

const walk = (root: string): string[] => {
  const result: string[] = [];
  const skip = new Set([".git", "node_modules", ".pi", ".opencode"]);
  const visit = (dir: string) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      if (entry.isDirectory() && !skip.has(entry.name)) visit(join(dir, entry.name));
      else if (entry.isFile() && entry.name.endsWith(".md")) result.push(join(dir, entry.name));
    }
  };
  visit(root);
  return result;
};

const nextAction = (root: string): string => {
  let taskName = "tasks.md";
  try {
    const configuration = readAsIsJson(join(root, "as-is.json")).configuration;
    taskName = taskRecordNameFromConfiguration(configuration);
  } catch (error) {
    if (error instanceof Error && error.message.includes("configuration.records.filenames.task must be a safe basename")) return "invalid configured task filename";
    /* legacy projects use the default */
  }
  const taskPath = join(root, taskName);
  let text: string;
  try {
    text = readFileSync(taskPath, "utf8");
  } catch {
    return "not recorded";
  }
  const heading = /^## Next Action\s*$/m.exec(text);
  if (!heading || heading.index === undefined) return "not recorded";
  const contentStart = heading.index + heading[0].length;
  const remainder = text.slice(contentStart);
  const nextSection = /\n## /m.exec(remainder);
  return remainder.slice(0, nextSection?.index ?? remainder.length).trim().replace(/\s+/g, " ") || "not recorded";
};

const changelog = (root: string): OrientationSnapshot["changelog"] => {
  const changelogPath = join(root, "changelog.md");
  const text = readFileSync(changelogPath, "utf8");
  const match = text.match(/^## Changelog\s*$([\s\S]*?)(?=^## |$)/m);
  const entry = match?.[1].trim() || "not recorded";
  const residualRisk: string[] = [];
  for (const line of entry.split("\n")) {
    if (/residual[- ]risk/i.test(line)) residualRisk.push(line.replace(/^[-*]\s*/, "").trim());
  }
  return { entry, residualRisk };
};

const decisions = (root: string): string[] => {
  const lines: string[] = [];
  for (const file of walk(root)) {
    const name = file.toLowerCase();
    if (!(name.includes("design") || name.includes("spec") || name.endsWith("independent-delegation.md"))) continue;
    readFileSync(file, "utf8").split("\n").forEach((line, index) => {
      if (/open decision|open question/i.test(line)) lines.push(`${relative(root, file)}:${index + 1}: ${line.trim()}`);
    });
  }
  return lines;
};

export function snapshot(root = process.cwd()): OrientationSnapshot {
  const resolved = resolve(root);
  const report = new ControlPlane(resolved).status() as { tasks: TaskSnapshot[] };
  const tasks = report.tasks.some((task) => task.path === ".")
